/** Sign → Major Arcana mapping (Golden Dawn correspondence) + date ranges */
export type ZodiacMap = { sign: string; cardId: string; from: [number, number]; to: [number, number]; dates: string; line: string };
export const ZODIAC: ZodiacMap[] = [
  { sign: "Aries", cardId: "the-emperor", from: [3, 21], to: [4, 19], dates: "March 21 – April 19", line: "Pioneering fire — you start what others only plan. Emperor energy: build structure for your boldness." },
  { sign: "Taurus", cardId: "the-hierophant", from: [4, 20], to: [5, 20], dates: "April 20 – May 20", line: "Steadfast earth — tradition and comfort matter to you. Hierophant energy: learn deeply, teach generously." },
  { sign: "Gemini", cardId: "the-lovers", from: [5, 21], to: [6, 20], dates: "May 21 – June 20", line: "Restless air — duality is your superpower. Lovers energy: choose alignment over options." },
  { sign: "Cancer", cardId: "the-chariot", from: [6, 21], to: [7, 22], dates: "June 21 – July 22", line: "Protective water — home is your fortress. Chariot energy: steer opposing forces with care." },
  { sign: "Leo", cardId: "strength", from: [7, 23], to: [8, 22], dates: "July 23 – August 22", line: "Radiant fire — courage with a warm heart. Strength energy: your gentleness IS the power." },
  { sign: "Virgo", cardId: "the-hermit", from: [8, 23], to: [9, 22], dates: "August 23 – September 22", line: "Analytical earth — the inner lantern. Hermit energy: your solitude is where wisdom ripens." },
  { sign: "Libra", cardId: "justice", from: [9, 23], to: [10, 22], dates: "September 23 – October 22", line: "Harmonising air — fairness is instinct. Justice energy: weigh honestly, then decide cleanly." },
  { sign: "Scorpio", cardId: "death", from: [10, 23], to: [11, 21], dates: "October 23 – November 21", line: "Deep water — transformation is your element. Death energy: you are the season's honest ending." },
  { sign: "Sagittarius", cardId: "temperance", from: [11, 22], to: [12, 21], dates: "November 22 – December 21", line: "Philosophical fire — blend and temper. Temperance energy: moderation makes your arrows fly straight." },
  { sign: "Capricorn", cardId: "the-devil", from: [12, 22], to: [1, 19], dates: "December 22 – January 19", line: "Patient earth — material mastery. Devil energy: command resources without being commanded by them." },
  { sign: "Aquarius", cardId: "the-star", from: [1, 20], to: [2, 18], dates: "January 20 – February 18", line: "Visionary air — the fixed star. Star energy: pour hope out; it refills." },
  { sign: "Pisces", cardId: "the-moon", from: [2, 19], to: [3, 20], dates: "February 19 – March 20", line: "Dreaming water — intuition as navigation. Moon energy: trust the tide, verify the map." },
];

export function zodiacByDate(m: number, d: number): ZodiacMap {
  const match = ZODIAC.find((z) => (m === z.from[0] && d >= z.from[1]) || (m === z.to[0] && d <= z.to[1]));
  return match ?? ZODIAC[11];
}

